    graph_entity_cleanup: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: {
            content: {
                "application/json": {
                    /**
                     * @description true = stage and delete; absent or false = dry run
                     * @default false
                     */
                    apply?: boolean;
                    /**
                     * @description how many of the most-connected junk entities to list
                     * @default 20
                     */
                    examples?: number;
                    /**
                     * @description most entities one applied run removes
                     * @default 5000
                     */
                    max_delete?: number;
                };
            };
        };
        responses: {
            /** @description The report (finished within the wait) */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @enum {string} */
                        status?: "dry-run" | "applied";
                        dry_run?: boolean;
                        scanned?: number;
                        junk?: number;
                        with_edges?: number;
                        edge_rows?: number;
                        with_mentions?: number;
                        mention_rows?: number;
                        in_clusters?: number;
                        cluster_rows?: number;
                        by_reason?: {
                            [key: string]: number;
                        };
                        by_type?: {
                            [key: string]: number;
                        };
                        examples?: {
                            name?: string;
                            type?: string;
                            reason?: string;
                            edges?: number;
                            mentions?: number;
                            clusters?: number;
                        }[];
                        staged?: number;
                        skipped_over_cap?: number;
                        run_id?: string | null;
                    };
                };
            };
            /** @description Still running: an operation handle */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["OperationHandle"];
                };
            };
            /** @description A parameter is out of range or `apply` is not a boolean */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Not an Admin (an Operator, a User, a service credential or an agent token) */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Busy: graph prune or a recluster is running; nothing was changed */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The audit row could not be written, so nothing was deleted; or the trellion add-on is off */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
